from numpy import*
T=array([str]*20)
M=array([float]*20)
def module(z):
    p=z.find('+')
    x=""
    y=""
    for i in range (p):
        x+=z[i]
    x=int(x)
    for i in range (p+1,len(z)-1):
        y+=z[i]
    y=int(y)
    w=sqrt(x*x+y*y)
    return w
def Saisie():
    b = 0
    while not(b):
        x=int(input("Donner le nombre des cases: "))
        b = 2 <= x <= 20
    return x
def RemplirT(N,T):
    for i in range(N):
        B = False
        while not(B):
            a=int(input("<Partie réelle: "))
            b=int(input("<<Partie imaginaire:: "))
            B = a>0 and b>0

        T[i]=str(a)+"+"+str(b)+"i"
def RemplirM(N,T,M):
    for i in range(N):
        M[i]=(module(T[i]))
def Tri_simultane(T,M,N):
        for i in range (N-1):
            idmax = maxi(M,i,N)
            if idmax!=i:
                temp1 = M[i]
                M[i] = M[idmax]
                M[idmax] = temp1
                temp2 = T[i]
                T[i] = T[idmax]
                T[idmax] = temp2
def maxi(t,a,b):
    p = a
    for i in range (a+1,b) :
        if t[i]>t[p]:
            p = i
    return p
def Afficher(M,N,T):
    print(T[0],end="")
    for i in range(1,N):
        if M[i]!=M[i-1]:
            print("\n")
        print(T[i],end="")

